10	
11	#include <fcntl.h>
12	#include <getopt.h>
13	#include <stdint.h>
14	#include <stdio.h>
15	#include <stdlib.h>
16	#include <string.h>
17	#include <unistd.h>
18	#include <errno.h>
19	#include <time.h>
20	
21	#include <sys/mman.h>
22	#include <sys/stat.h>
23	#include <sys/time.h>
24	#include <sys/types.h>
25	#include <sys/ioctl.h>
26	
27	#include "../xdma/cdev_sgdma.h"
28	
29	#include "dma_utils.c"
30	
31	static struct option const long_opts[] = {
32		{"device", required_argument, NULL, 'd'},
33		{"address", required_argument, NULL, 'a'},
34		{"aperture", required_argument, NULL, 'k'},
35		{"size", required_argument, NULL, 's'},
36		{"offset", required_argument, NULL, 'o'},
37		{"count", required_argument, NULL, 'c'},
38		{"data infile", required_argument, NULL, 'f'},
39		{"data outfile", required_argument, NULL, 'w'},
40		{"help", no_argument, NULL, 'h'},
41		{"verbose", no_argument, NULL, 'v'},
42		{0, 0, 0, 0}
43	};
44	
45	#define DEVICE_NAME_DEFAULT "/dev/xdma0_h2c_0"
46	#define SIZE_DEFAULT (32)
47	#define COUNT_DEFAULT (1)
48	
49	
50	static int test_dma(char *devname, uint64_t addr, uint64_t aperture,
51			    uint64_t size, uint64_t offset, uint64_t count,
52			    char *filename, char *);
53	
54	static void usage(const char *name)
55	{
56		int i = 0;
57	
58		fprintf(stdout, "%s\n\n", name);
59		fprintf(stdout, "usage: %s [OPTIONS]\n\n", name);
60		fprintf(stdout, 
61			"Write via SGDMA, optionally read input from a file.\n\n");
62	
63		fprintf(stdout, "  -%c (--%s) device (defaults to %s)\n",
64			long_opts[i].val, long_opts[i].name, DEVICE_NAME_DEFAULT);
65		i++;
66		fprintf(stdout, "  -%c (--%s) the start address on the AXI bus\n",
67			long_opts[i].val, long_opts[i].name);
68		i++;
69		fprintf(stdout, "  -%c (--%s) memory address aperture\n",
70			long_opts[i].val, long_opts[i].name);
71		i++;
72		fprintf(stdout,
73			"  -%c (--%s) size of a single transfer in bytes, default %d,\n",
74			long_opts[i].val, long_opts[i].name, SIZE_DEFAULT);
75		i++;
76		fprintf(stdout, "  -%c (--%s) page offset of transfer\n",
77			long_opts[i].val, long_opts[i].name);
78		i++;
79		fprintf(stdout, "  -%c (--%s) number of transfers, default %d\n",
80			long_opts[i].val, long_opts[i].name, COUNT_DEFAULT);
81		i++;
82		fprintf(stdout, "  -%c (--%s) filename to read the data from.\n",
83			long_opts[i].val, long_opts[i].name);
84		i++;
85		fprintf(stdout,
86			"  -%c (--%s) filename to write the data of the transfers\n",
87			long_opts[i].val, long_opts[i].name);
88		i++;
89		fprintf(stdout, "  -%c (--%s) print usage help and exit\n",
90			long_opts[i].val, long_opts[i].name);
91		i++;
92		fprintf(stdout, "  -%c (--%s) verbose output\n",
93			long_opts[i].val, long_opts[i].name);
94		i++;
95	
96		fprintf(stdout, "\nReturn code:\n");
97		fprintf(stdout, "  0: all bytes were dma'ed successfully\n");
98		fprintf(stdout, "  < 0: error\n\n");
99	}
100	
101	int main(int argc, char *argv[])
102	{
103		int cmd_opt;
104		char *device = DEVICE_NAME_DEFAULT;
105		uint64_t address = 0;
106		uint64_t aperture = 0;
107		uint64_t size = SIZE_DEFAULT;
108		uint64_t offset = 0;
109		uint64_t count = COUNT_DEFAULT;
110		char *infname = NULL;
111		char *ofname = NULL;
112	
113		while ((cmd_opt =
114			getopt_long(argc, argv, "vhc:f:d:a:k:s:o:w:", long_opts,
115				    NULL)) != -1) {
116			switch (cmd_opt) {
117			case 0:
118				/* long option */
119				break;
120			case 'd':
121				/* device node name */
122				//fprintf(stdout, "'%s'\n", optarg);
123				device = strdup(optarg);
124				break;
125			case 'a':
126				/* RAM address on the AXI bus in bytes */
127				address = getopt_integer(optarg);
128				break;
129			case 'k':
130				/* memory aperture windows size */
131				aperture = getopt_integer(optarg);
132				break;
133			case 's':
134				/* size in bytes */
135				size = getopt_integer(optarg);
136				break;
137			case 'o':
138				offset = getopt_integer(optarg) & 4095;
139				break;
140				/* count */
141			case 'c':
142				count = getopt_integer(optarg);
143				break;
144				/* count */
145			case 'f':
146				infname = strdup(optarg);
147				break;
148			case 'w':
149				ofname = strdup(optarg);
150				break;
151				/* print usage help and exit */
152			case 'v':
153				verbose = 1;
154				break;
155			case 'h':
156			default:
157				usage(argv[0]);
158				exit(0);
159				break;
160			}
161		}
162	
163		if (verbose)
164			fprintf(stdout, 
165			"dev %s, addr 0x%lx, aperture 0x%lx, size 0x%lx, offset 0x%lx, "
166		        "count %lu\n",
167			device, address, aperture, size, offset, count);
168	
169		return test_dma(device, address, aperture, size, offset, count,
170				infname, ofname);
171	}
172	
173	static int test_dma(char *devname, uint64_t addr, uint64_t aperture,
174			    uint64_t size, uint64_t offset, uint64_t count,
175			    char *infname, char *ofname)
176	{
177		uint64_t i;
178		ssize_t rc;
179		size_t bytes_done = 0;
180		size_t out_offset = 0;
181		char *buffer = NULL;
182		char *allocated = NULL;
183		struct timespec ts_start, ts_end;
184		int infile_fd = -1;
185		int outfile_fd = -1;
186		int fpga_fd = open(devname, O_RDWR);
187		long total_time = 0;
188		float result;
189		float avg_time = 0;
190		int underflow = 0;
191	
192		if (fpga_fd < 0) {
193			fprintf(stderr, "unable to open device %s, %d.\n",
194				devname, fpga_fd);
195			perror("open device");
196			return -EINVAL;
197		}
198	
199		if (infname) {
200			infile_fd = open(infname, O_RDONLY);
201			if (infile_fd < 0) {
202				fprintf(stderr, "unable to open input file %s, %d.\n",
203					infname, infile_fd);
204				perror("open input file");
205				rc = -EINVAL;
206				goto out;
207			}
208		}
209	
210		if (ofname) {
211			outfile_fd =
212			    open(ofname, O_RDWR | O_CREAT | O_TRUNC | O_SYNC,
213				 0666);
214			if (outfile_fd < 0) {
215				fprintf(stderr, "unable to open output file %s, %d.\n",
216					ofname, outfile_fd);
217				perror("open output file");
218				rc = -EINVAL;
219				goto out;
220			}
221		}
222	
223		posix_memalign((void **)&allocated, 4096 /*alignment */ , size + 4096);
224		if (!allocated) {
225			fprintf(stderr, "OOM %lu.\n", size + 4096);
226			rc = -ENOMEM;
227			goto out;
228		}
229		buffer = allocated + offset;
230		if (verbose)
231			fprintf(stdout, "host buffer 0x%lx = %p\n",
232				size + 4096, buffer); 
233	
234		if (infile_fd >= 0) {
235			rc = read_to_buffer(infname, infile_fd, buffer, size, 0);
236			if (rc < 0 || rc < size)
237				goto out;
238		}
239	
240		for (i = 0; i < count; i++) {
241			/* write buffer to AXI MM address using SGDMA */
242			rc = clock_gettime(CLOCK_MONOTONIC, &ts_start);
243	
244			if (aperture) {
245				struct xdma_aperture_ioctl io;
246	
247				io.buffer = (unsigned long)buffer;
248				io.len = size;
249				io.ep_addr = addr;
250				io.aperture = aperture;
251				io.done = 0UL;
252	
253				rc = ioctl(fpga_fd, IOCTL_XDMA_APERTURE_W, &io);
254				if (rc < 0 || io.error) {
255					fprintf(stdout,
256						"#%d: aperture W ioctl failed %d,%d.\n",
257						i, rc, io.error);
258					goto out;
259				}
260	
261				bytes_done = io.done;
262			} else {
263				rc = write_from_buffer(devname, fpga_fd, buffer, size,
264					      	 	addr);
265				if (rc < 0)
266					goto out;
267	
268				bytes_done = rc;
269			}
270	
271			rc = clock_gettime(CLOCK_MONOTONIC, &ts_end);
272	
273			if (bytes_done < size) {
274				printf("#%d: underflow %ld/%ld.\n",
275					i, bytes_done, size);
276				underflow = 1;
277			}
278	
279			/* subtract the start time from the end time */
280			timespec_sub(&ts_end, &ts_start);
281			total_time += ts_end.tv_nsec;
282			/* a bit less accurate but side-effects are accounted for */
283			if (verbose)
284			fprintf(stdout,
285				"#%lu: CLOCK_MONOTONIC %ld.%09ld sec. write %ld bytes\n",
286				i, ts_end.tv_sec, ts_end.tv_nsec, size); 
287				
288			if (outfile_fd >= 0) {
289				rc = write_from_buffer(ofname, outfile_fd, buffer,
290							 bytes_done, out_offset);
291				if (rc < 0 || rc < bytes_done)
292					goto out;
293				out_offset += bytes_done;
294			}
295		}
296	
297		if (!underflow) {
298			avg_time = (float)total_time/(float)count;
299			result = ((float)size)*1000/avg_time;
300			if (verbose)
301				printf("** Avg time device %s, total time %ld nsec, avg_time = %f, size = %lu, BW = %f \n",
302				devname, total_time, avg_time, size, result);
303			printf("%s ** Average BW = %lu, %f\n", devname, size, result);
304		}
305	
306	out:
307		close(fpga_fd);
308		if (infile_fd >= 0)
309			close(infile_fd);
310		if (outfile_fd >= 0)
311			close(outfile_fd);
312		free(allocated);
313	
314		if (rc < 0)
315			return rc;
316		/* treat underflow as error */
317		return underflow ? -EIO : 0;
318	}
