/*
 * This file is part of the Xilinx DMA IP Core driver tools for Linux
 *
 * Copyright (c) 2016-present,  Xilinx, Inc.
 * All rights reserved.
 *
 * This source code is licensed under BSD-style license (found in the
 * LICENSE file in the root directory of this source tree)
 */

#include <stdio.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <errno.h>
#include <sys/types.h>

/*
 * man 2 write:
 * On Linux, write() (and similar system calls) will transfer at most
 * 	0x7ffff000 (2,147,479,552) bytes, returning the number of bytes
 *	actually transferred.  (This is true on both 32-bit and 64-bit
 *	systems.)
 */

#define RW_MAX_SIZE	0x7ffff000

int verbose = 0;

uint64_t getopt_integer(char *optarg)
{
	int rc;
	uint64_t value;

	rc = sscanf(optarg, "0x%lx", &value);
	if (rc <= 0)
		rc = sscanf(optarg, "%lu", &value);
	//printf("sscanf() = %d, value = 0x%lx\n", rc, value);

	return value;
}

ssize_t read_to_buffer(char *fname, int fd, char *buffer, uint64_t size,
			uint64_t base)
{
	ssize_t rc;
	uint64_t count = 0;
	char *buf = buffer;
	off_t offset = base;
	int loop = 0;

	while (count < size) {
		uint64_t bytes = size - count;

		if (bytes > RW_MAX_SIZE)
			bytes = RW_MAX_SIZE;

		if (offset) {
			rc = lseek(fd, offset, SEEK_SET);
			if (rc != offset) {
				fprintf(stderr, "%s, seek off 0x%lx != 0x%lx.\n",
					fname, rc, offset);
				perror("seek file");
				return -EIO;
			}
		}

		/* read data from file into memory buffer */
		rc = read(fd, buf, bytes);
		if (rc < 0) {
			fprintf(stderr, "%s, read 0x%lx @ 0x%lx failed %ld.\n",
				fname, bytes, offset, rc);
			perror("read file");
			return -EIO;
		}

		count += rc;
		if (rc != bytes) {
			fprintf(stderr, "%s, read underflow 0x%lx/0x%lx @ 0x%lx.\n",
				fname, rc, bytes, offset);
			break;
		}

		buf += bytes;
		offset += bytes;
		loop++;
	}

	if (count != size && loop)
		fprintf(stderr, "%s, read underflow 0x%lx/0x%lx.\n",
			fname, count, size);
	return count;
}

ssize_t write_from_buffer(char *fname, int fd, char *buffer, uint64_t size,
			uint64_t base)
{
	ssize_t rc;
	uint64_t count = 0;
	char *buf = buffer;
	off_t offset = base;
	int loop = 0;

	while (count < size) {
		uint64_t bytes = size - count;

		if (bytes > RW_MAX_SIZE)
			bytes = RW_MAX_SIZE;

		if (offset) {
			rc = lseek(fd, offset, SEEK_SET);
			if (rc != offset) {
				fprintf(stderr, "%s, seek off 0x%lx != 0x%lx.\n",
					fname, rc, offset);
				perror("seek file");
				return -EIO;
			}
		}

		/* write data to file from memory buffer */
		rc = write(fd, buf, bytes);
		if (rc < 0) {
			fprintf(stderr, "%s, write 0x%lx @ 0x%lx failed %ld.\n",
				fname, bytes, offset, rc);
			perror("write file");
			return -EIO;
		}

		count += rc;
		if (rc != bytes) {
			fprintf(stderr, "%s, write underflow 0x%lx/0x%lx @ 0x%lx.\n",
				fname, rc, bytes, offset);
			break;
		}
		buf += bytes;
		offset += bytes;

		loop++;
	}	

	if (count != size && loop)
		fprintf(stderr, "%s, write underflow 0x%lx/0x%lx.\n",
			fname, count, size);

	return count;
}


/* Subtract timespec t2 from t1
 *
 * Both t1 and t2 must already be normalized
 * i.e. 0 <= nsec < 1000000000
 */
static int timespec_check(struct timespec *t)
{
	if ((t->tv_nsec < 0) || (t->tv_nsec >= 1000000000))
		return -1;
	return 0;

}

void timespec_sub(struct timespec *t1, struct timespec *t2)
{
	if (timespec_check(t1) < 0) {
		fprintf(stderr, "invalid time #1: %lld.%.9ld.\n",
			(long long)t1->tv_sec, t1->tv_nsec);
		return;
	}
	if (timespec_check(t2) < 0) {
		fprintf(stderr, "invalid time #2: %lld.%.9ld.\n",
			(long long)t2->tv_sec, t2->tv_nsec);
		return;
	}
	t1->tv_sec -= t2->tv_sec;
	t1->tv_nsec -= t2->tv_nsec;
	if (t1->tv_nsec >= 1000000000) {
		t1->tv_sec++;
		t1->tv_nsec -= 1000000000;
	} else if (t1->tv_nsec < 0) {
		t1->tv_sec--;
		t1->tv_nsec += 1000000000;
	}
}

// npu_ctrl_lite.v
// AXI4-Lite slave providing a single CTRL/STATUS register to the host.
//
// Register map (byte offsets, 32-bit words):
//   0x000  CTRL
//          [0] start  W  : host writes 1 to assert a 1-cycle start pulse (self-clears)
//          [1] done   RO : asserted for one cycle when npu_dma_master finishes WRITE_OUT
//          [2] busy   RO : asserted while npu_dma_master is active
//          [31:3] reserved, reads 0
//
// AXI clock domain : axi_aclk (250 MHz from XDMA)
// Connected to     : XDMA M_AXI_BYPASS port (128-bit wide at top, but AXI-Lite
//                    is 32-bit here; Vivado inserts dwidth converter in top_npu.v)
//
`timescale 1ns/1ps

module npu_ctrl_lite #(
    parameter ADDR_WIDTH = 12,   // 4 KB address space
    parameter DATA_WIDTH = 32
) (
    // AXI4-Lite slave interface
    input  wire                  axi_aclk,
    input  wire                  axi_aresetn,

    // Write address channel
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire [2:0]            s_axil_awprot,
    input  wire                  s_axil_awvalid,
    output reg                   s_axil_awready,

    // Write data channel
    input  wire [DATA_WIDTH-1:0] s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output reg                   s_axil_wready,

    // Write response channel
    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,

    // Read address channel
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire [2:0]            s_axil_arprot,
    input  wire                  s_axil_arvalid,
    output reg                   s_axil_arready,

    // Read data channel
    output reg  [DATA_WIDTH-1:0] s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,

    // User-side signals
    output reg                   start,   // 1-cycle pulse to npu_dma_master
    input  wire                  done,    // from npu_dma_master (1-cycle pulse)
    input  wire                  busy     // from npu_dma_master (level)
);

    // -----------------------------------------------------------------------
    // Internal CTRL register (only bit 0 is writable; bits 1-2 are RO)
    // -----------------------------------------------------------------------
    reg         ctrl_start_r;  // sticky until cleared below

    // Latch done/busy for read-back (done is a pulse; hold until next start)
    reg         done_latch;

    always @(posedge axi_aclk) begin
        if (!axi_aresetn) begin
            done_latch <= 1'b0;
        end else begin
            if (done)
                done_latch <= 1'b1;
            else if (start)          // clear done when a new start fires
                done_latch <= 1'b0;
        end
    end

    // -----------------------------------------------------------------------
    // Write path
    // -----------------------------------------------------------------------
    // We accept AW and W simultaneously (AXI-Lite burst=1 always).
    // State: 0=idle/ready, 1=wait-for-W, 2=send-B
    reg [1:0] wr_state;
    localparam WR_IDLE = 2'd0,
               WR_DATA = 2'd1,
               WR_RESP = 2'd2;

    reg [ADDR_WIDTH-1:0] aw_addr_r;

    always @(posedge axi_aclk) begin
        if (!axi_aresetn) begin
            wr_state      <= WR_IDLE;
            s_axil_awready <= 1'b0;
            s_axil_wready  <= 1'b0;
            s_axil_bvalid  <= 1'b0;
            s_axil_bresp   <= 2'b00;
            ctrl_start_r   <= 1'b0;
            start          <= 1'b0;
        end else begin
            start <= 1'b0;  // default: no pulse

            case (wr_state)
                WR_IDLE: begin
                    s_axil_awready <= 1'b1;
                    s_axil_wready  <= 1'b1;
                    if (s_axil_awvalid && s_axil_awready) begin
                        aw_addr_r      <= s_axil_awaddr;
                        s_axil_awready <= 1'b0;
                        if (s_axil_wvalid && s_axil_wready) begin
                            // AW and W arrived together
                            wr_state      <= WR_RESP;
                            s_axil_wready <= 1'b0;
                            s_axil_bvalid <= 1'b1;
                            s_axil_bresp  <= 2'b00;
                            // Decode write
                            if (s_axil_awaddr[ADDR_WIDTH-1:2] == 0) begin
                                // CTRL register
                                if (s_axil_wstrb[0] && s_axil_wdata[0]) begin
                                    ctrl_start_r <= 1'b1;
                                    start        <= 1'b1;
                                end
                            end
                        end else begin
                            wr_state <= WR_DATA;
                        end
                    end
                end

                WR_DATA: begin
                    if (s_axil_wvalid && s_axil_wready) begin
                        wr_state      <= WR_RESP;
                        s_axil_wready <= 1'b0;
                        s_axil_bvalid <= 1'b1;
                        s_axil_bresp  <= 2'b00;
                        if (aw_addr_r[ADDR_WIDTH-1:2] == 0) begin
                            if (s_axil_wstrb[0] && s_axil_wdata[0]) begin
                                ctrl_start_r <= 1'b1;
                                start        <= 1'b1;
                            end
                        end
                    end
                end

                WR_RESP: begin
                    ctrl_start_r <= 1'b0;
                    if (s_axil_bvalid && s_axil_bready) begin
                        s_axil_bvalid  <= 1'b0;
                        wr_state       <= WR_IDLE;
                        s_axil_awready <= 1'b1;
                        s_axil_wready  <= 1'b1;
                    end
                end

                default: wr_state <= WR_IDLE;
            endcase
        end
    end

    // -----------------------------------------------------------------------
    // Read path
    // -----------------------------------------------------------------------
    reg [1:0] rd_state;
    localparam RD_IDLE = 2'd0,
               RD_DATA = 2'd1;

    reg [ADDR_WIDTH-1:0] ar_addr_r;

    always @(posedge axi_aclk) begin
        if (!axi_aresetn) begin
            rd_state       <= RD_IDLE;
            s_axil_arready <= 1'b0;
            s_axil_rvalid  <= 1'b0;
            s_axil_rdata   <= {DATA_WIDTH{1'b0}};
            s_axil_rresp   <= 2'b00;
        end else begin
            case (rd_state)
                RD_IDLE: begin
                    s_axil_arready <= 1'b1;
                    if (s_axil_arvalid && s_axil_arready) begin
                        ar_addr_r      <= s_axil_araddr;
                        s_axil_arready <= 1'b0;
                        rd_state       <= RD_DATA;
                        s_axil_rvalid  <= 1'b1;
                        s_axil_rresp   <= 2'b00;
                        // Latch read data
                        if (s_axil_araddr[ADDR_WIDTH-1:2] == 0) begin
                            // CTRL/STATUS register
                            s_axil_rdata <= {
                                {DATA_WIDTH-3{1'b0}},
                                busy,           // [2]
                                done_latch,     // [1]
                                1'b0            // [0] start is W-only, reads 0
                            };
                        end else begin
                            s_axil_rdata <= {DATA_WIDTH{1'b0}};
                        end
                    end
                end

                RD_DATA: begin
                    if (s_axil_rvalid && s_axil_rready) begin
                        s_axil_rvalid  <= 1'b0;
                        rd_state       <= RD_IDLE;
                        s_axil_arready <= 1'b1;
                    end
                end

                default: rd_state <= RD_IDLE;
            endcase
        end
    end

endmodule

"""
reg_rw.py — Wrapper around the remote reg_rw C tool for BAR register access.

Provides a clean Python API for reading/writing 32-bit registers in the
XDMA AXI-Lite user BAR or bypass BAR.
"""

from __future__ import annotations
from . import ssh, xdma

# ctrl_lite register map (byte offsets)
REG_CTRL     = 0x00   # [0]=start(W1S), [1]=done(R), [2]=busy(R)

# Discovery: which BAR device to use for ctrl_lite
# XDMA config: BAR0 → axist_bypass (128-bit) → split to user/bypass devices
# Try /dev/xdma0_user first (AXI-Lite user), then /dev/xdma0_bypass
CANDIDATE_DEVS = [
    "/dev/xdma0_user",
    "/dev/xdma0_bypass",
]
_SENTINEL = 0x0000_0000  # uninitialized/disconnected reads come back as 0


class BARError(RuntimeError):
    pass


class BARDevice:
    """
    Access the ctrl_lite register block through the XDMA bypass/user BAR.
    Automatically discovers which device node works.
    """

    def __init__(self, host: str, device: str | None = None):
        self.host = host
        self._dev = device or self._discover()

    @property
    def device(self) -> str:
        return self._dev

    def _discover(self) -> str:
        """Try candidate devices and return the first that doesn't error."""
        xd = xdma.XDMADevice(self.host)
        for dev in CANDIDATE_DEVS:
            try:
                xd.reg_read(dev, 0x0)
                return dev
            except Exception:
                continue
        raise BARError(
            f"Cannot access ctrl_lite via any of {CANDIDATE_DEVS}. "
            "Check that the XDMA driver is loaded and ctrl_lite is mapped."
        )

    def read(self, offset: int) -> int:
        """Read 32-bit register at *offset*."""
        return xdma.XDMADevice(self.host).reg_read(self._dev, offset)

    def write(self, offset: int, value: int) -> None:
        """Write 32-bit register at *offset*."""
        xdma.XDMADevice(self.host).reg_write(self._dev, offset, value)

    # ── ctrl_lite helpers ───────────────────────────────────────────────────

    def ctrl_read(self) -> int:
        return self.read(REG_CTRL)

    @property
    def is_done(self) -> bool:
        return bool((self.ctrl_read() >> 1) & 1)

    @property
    def is_busy(self) -> bool:
        return bool((self.ctrl_read() >> 2) & 1)

    def kick_start(self) -> None:
        """Assert start=1 to trigger the NPU FSM."""
        self.write(REG_CTRL, 0x1)

    def wait_done(self, timeout_s: int = 10) -> bool:
        """Poll until done=1 or *timeout_s* seconds elapsed. Returns True on success."""
        import time
        deadline = time.monotonic() + timeout_s
        while time.monotonic() < deadline:
            if self.is_done:
                return True
            time.sleep(0.01)
        return False

