250	    localparam ARLEN_AB   = 8'd1;
251	    localparam ARLEN_FULL = 8'd7;
252	
253	    always @(posedge aclk) begin
254	        if (!aresetn) begin
255	            state             <= S_IDLE;
256	            busy              <= 1'b0;
257	            done              <= 1'b0;
258	            beat_cnt          <= 4'd0;
259	            read_timeout_cnt  <= 16'h0;
260	            m_axi_arvalid     <= 1'b0;
261	            m_axi_rready      <= 1'b0;
262	            m_axi_awvalid     <= 1'b0;
263	            m_axi_wvalid      <= 1'b0;
264	            m_axi_bready      <= 1'b0;
265	            io_ctrl_keep      <= 1'b0;
266	            io_ctrl_use_accum <= 1'b0;
267	            io_ctrl_busy      <= 1'b0;
268	            m_axi_awid    <= AXI_ID;
269	            m_axi_awsize  <= AXI_SIZE_128;
270	            m_axi_awburst <= AXI_BURST_INCR;
271	            m_axi_awlock  <= 1'b0;
272	            m_axi_awcache <= 4'b0010;
273	            m_axi_awprot  <= 3'b000;
274	            m_axi_awqos   <= 4'b0000;
275	            m_axi_wstrb   <= {(AXI_DATA_WIDTH/8){1'b1}};
276	            m_axi_arid    <= AXI_ID;
277	            m_axi_arsize  <= AXI_SIZE_128;
278	            m_axi_arburst <= AXI_BURST_INCR;
279	            m_axi_arlock  <= 1'b0;
280	            m_axi_arcache <= 4'b0010;
281	            m_axi_arprot  <= 3'b000;
282	            m_axi_arqos   <= 4'b0000;
283	        end else begin
284	            done <= 1'b0;
285	
286	            case (state)
287	                // ----------------------------------------------------------
288	                S_IDLE: begin
289	                    busy         <= 1'b0;
290	                    io_ctrl_keep <= 1'b0;
291	                    if (start) begin
292	                        busy  <= 1'b1;
293	                        state <= S_READ_A_AR;
294	                    end
295	                end
296	
297	                // ----------------------------------------------------------
298	                // Read matrix A (32 B, 2 beats, ARLEN=1)
299	                // ----------------------------------------------------------
300	                S_READ_A_AR: begin
301	                    m_axi_araddr  <= DEFAULT_BASE_A;
302	                    m_axi_arlen   <= ARLEN_AB;
303	                    m_axi_arvalid <= 1'b1;
304	                    beat_cnt      <= 4'd0;
305	                    if (m_axi_arready && m_axi_arvalid) begin
306	                        m_axi_arvalid <= 1'b0;
307	                        // Keep rready asserted across read phases: deasserting it
308	                        // between A's rlast and the next AR handshake lets the
309	                        // dwidth-converter/xbar chain stall and LOSE the first
310	                        // beat of the next burst (intermittent S_READ_B_R hang).
311	                        m_axi_rready  <= 1'b1;
312	                        state         <= S_READ_A_R;
313	                    end
314	                end
315	
316	                S_READ_A_R: begin
317	                    // Do NOT deassert rready on rlast — see S_READ_A_AR comment.
318	                    // Read-timeout retry: re-issue the AR if the transaction is
319	                    // dropped by the xbar/dwidth chain (no beat for a long time).
320	                    if (rpipe_use)
321	                        read_timeout_cnt <= 16'h0;
322	                    else if (read_timeout_cnt != READ_TIMEOUT_MAX)
323	                        read_timeout_cnt <= read_timeout_cnt + 16'h1;
324	                    if (read_timeout_cnt == READ_TIMEOUT_MAX) begin
325	                        read_timeout_cnt <= 16'h0;
326	                        state            <= S_READ_A_AR;
327	                    end
328	                    // Buffer unpack from pipeline register (1 cycle after acceptance)
329	                    if (rpipe_use) begin
330	                        // beat N: bytes [beat_cnt*16 .. beat_cnt*16+15]
331	                        a_buf[beat_cnt*16 + 0]  <= rdata_pipe[7:0];
332	                        a_buf[beat_cnt*16 + 1]  <= rdata_pipe[15:8];
333	                        a_buf[beat_cnt*16 + 2]  <= rdata_pipe[23:16];
334	                        a_buf[beat_cnt*16 + 3]  <= rdata_pipe[31:24];
335	                        a_buf[beat_cnt*16 + 4]  <= rdata_pipe[39:32];
336	                        a_buf[beat_cnt*16 + 5]  <= rdata_pipe[47:40];
337	                        a_buf[beat_cnt*16 + 6]  <= rdata_pipe[55:48];
338	                        a_buf[beat_cnt*16 + 7]  <= rdata_pipe[63:56];
339	                        a_buf[beat_cnt*16 + 8]  <= rdata_pipe[71:64];
340	                        a_buf[beat_cnt*16 + 9]  <= rdata_pipe[79:72];
341	                        a_buf[beat_cnt*16 + 10] <= rdata_pipe[87:80];
342	                        a_buf[beat_cnt*16 + 11] <= rdata_pipe[95:88];
343	                        a_buf[beat_cnt*16 + 12] <= rdata_pipe[103:96];
344	                        a_buf[beat_cnt*16 + 13] <= rdata_pipe[111:104];
345	                        a_buf[beat_cnt*16 + 14] <= rdata_pipe[119:112];
346	                        a_buf[beat_cnt*16 + 15] <= rdata_pipe[127:120];
347	                        beat_cnt <= beat_cnt + 1;
348	                        if (rlast_pipe)
349	                            state <= S_READ_B_AR;
350	                    end
351	                end
352	
353	                // ----------------------------------------------------------
354	                // Read matrix B (32 B, 2 beats)
355	                // ----------------------------------------------------------
356	                S_READ_B_AR: begin
357	                    m_axi_araddr  <= DEFAULT_BASE_B;
358	                    m_axi_arlen   <= ARLEN_AB;
359	                    m_axi_arvalid <= 1'b1;
360	                    beat_cnt      <= 4'd0;
361	                    if (m_axi_arready && m_axi_arvalid) begin
362	                        m_axi_arvalid <= 1'b0;
363	                        // rready stays asserted (see S_READ_A_AR comment)
364	                        state         <= S_READ_B_R;
365	                    end
366	                end
367	
368	                S_READ_B_R: begin
369	                    // rready stays asserted (see S_READ_A_AR comment)
370	                    // Read-timeout retry: re-issue the B AR if dropped.
371	                    if (rpipe_use)
372	                        read_timeout_cnt <= 16'h0;
373	                    else if (read_timeout_cnt != READ_TIMEOUT_MAX)
374	                        read_timeout_cnt <= read_timeout_cnt + 16'h1;
375	                    if (read_timeout_cnt == READ_TIMEOUT_MAX) begin
376	                        read_timeout_cnt <= 16'h0;
377	                        state            <= S_READ_B_AR;
378	                    end
379	                    if (rpipe_use) begin
380	                        b_buf[beat_cnt*16 + 0]  <= rdata_pipe[7:0];
381	                        b_buf[beat_cnt*16 + 1]  <= rdata_pipe[15:8];
382	                        b_buf[beat_cnt*16 + 2]  <= rdata_pipe[23:16];
383	                        b_buf[beat_cnt*16 + 3]  <= rdata_pipe[31:24];
384	                        b_buf[beat_cnt*16 + 4]  <= rdata_pipe[39:32];
385	                        b_buf[beat_cnt*16 + 5]  <= rdata_pipe[47:40];
386	                        b_buf[beat_cnt*16 + 6]  <= rdata_pipe[55:48];
387	                        b_buf[beat_cnt*16 + 7]  <= rdata_pipe[63:56];
388	                        b_buf[beat_cnt*16 + 8]  <= rdata_pipe[71:64];
389	                        b_buf[beat_cnt*16 + 9]  <= rdata_pipe[79:72];
390	                        b_buf[beat_cnt*16 + 10] <= rdata_pipe[87:80];
391	                        b_buf[beat_cnt*16 + 11] <= rdata_pipe[95:88];
392	                        b_buf[beat_cnt*16 + 12] <= rdata_pipe[103:96];
393	                        b_buf[beat_cnt*16 + 13] <= rdata_pipe[111:104];
394	                        b_buf[beat_cnt*16 + 14] <= rdata_pipe[119:112];
395	                        b_buf[beat_cnt*16 + 15] <= rdata_pipe[127:120];
396	                        beat_cnt <= beat_cnt + 1;
397	                        if (rlast_pipe)
398	                            state <= S_READ_ACC_AR;
399	                    end
400	                end
401	
402	                // ----------------------------------------------------------
403	                // Read accumulator init (128 B, 8 beats, ARLEN=7)
404	                // ----------------------------------------------------------
405	                S_READ_ACC_AR: begin
406	                    m_axi_araddr  <= DEFAULT_BASE_ACCUM;
407	                    m_axi_arlen   <= ARLEN_FULL;
408	                    m_axi_arvalid <= 1'b1;
409	                    beat_cnt      <= 4'd0;
410	                    if (m_axi_arready && m_axi_arvalid) begin
411	                        m_axi_arvalid <= 1'b0;
412	                        // rready stays asserted (see S_READ_A_AR comment)
413	                        state         <= S_READ_ACC_R;
414	                    end
415	                end
416	
417	                S_READ_ACC_R: begin
418	                    // rready stays asserted (see S_READ_A_AR comment)
419	                    // Read-timeout retry: re-issue the ACCUM AR if dropped.
420	                    if (rpipe_use)
421	                        read_timeout_cnt <= 16'h0;
422	                    else if (read_timeout_cnt != READ_TIMEOUT_MAX)
423	                        read_timeout_cnt <= read_timeout_cnt + 16'h1;
424	                    if (read_timeout_cnt == READ_TIMEOUT_MAX) begin
425	                        read_timeout_cnt <= 16'h0;
426	                        state            <= S_READ_ACC_AR;
427	                    end
428	                    if (rpipe_use) begin
429	                        // 4 words per beat
430	                        acc_buf[beat_cnt*4 + 0] <= rdata_pipe[31:0];
431	                        acc_buf[beat_cnt*4 + 1] <= rdata_pipe[63:32];
432	                        acc_buf[beat_cnt*4 + 2] <= rdata_pipe[95:64];
433	                        acc_buf[beat_cnt*4 + 3] <= rdata_pipe[127:96];
434	                        beat_cnt <= beat_cnt + 1;
435	                        if (rlast_pipe)
436	                            state <= S_KICK;
437	                    end
438	                end
439	
440	                // ----------------------------------------------------------
441	                // Drive MMALU ports and pulse io_ctrl_busy
442	                // ----------------------------------------------------------
443	                S_KICK: begin
444	                    io_in_a_0  <= a_buf[0];  io_in_a_1  <= a_buf[1];
445	                    io_in_a_2  <= a_buf[2];  io_in_a_3  <= a_buf[3];
446	                    io_in_a_4  <= a_buf[4];  io_in_a_5  <= a_buf[5];
447	                    io_in_a_6  <= a_buf[6];  io_in_a_7  <= a_buf[7];
448	                    io_in_a_8  <= a_buf[8];  io_in_a_9  <= a_buf[9];
449	                    io_in_a_10 <= a_buf[10]; io_in_a_11 <= a_buf[11];
450	                    io_in_a_12 <= a_buf[12]; io_in_a_13 <= a_buf[13];
451	                    io_in_a_14 <= a_buf[14]; io_in_a_15 <= a_buf[15];
452	                    io_in_a_16 <= a_buf[16]; io_in_a_17 <= a_buf[17];
453	                    io_in_a_18 <= a_buf[18]; io_in_a_19 <= a_buf[19];
454	                    io_in_a_20 <= a_buf[20]; io_in_a_21 <= a_buf[21];
455	                    io_in_a_22 <= a_buf[22]; io_in_a_23 <= a_buf[23];
456	                    io_in_a_24 <= a_buf[24]; io_in_a_25 <= a_buf[25];
457	                    io_in_a_26 <= a_buf[26]; io_in_a_27 <= a_buf[27];
458	                    io_in_a_28 <= a_buf[28]; io_in_a_29 <= a_buf[29];
459	                    io_in_a_30 <= a_buf[30]; io_in_a_31 <= a_buf[31];
460	
461	                    io_in_b_0  <= b_buf[0];  io_in_b_1  <= b_buf[1];
462	                    io_in_b_2  <= b_buf[2];  io_in_b_3  <= b_buf[3];
463	                    io_in_b_4  <= b_buf[4];  io_in_b_5  <= b_buf[5];
464	                    io_in_b_6  <= b_buf[6];  io_in_b_7  <= b_buf[7];
465	                    io_in_b_8  <= b_buf[8];  io_in_b_9  <= b_buf[9];
466	                    io_in_b_10 <= b_buf[10]; io_in_b_11 <= b_buf[11];
467	                    io_in_b_12 <= b_buf[12]; io_in_b_13 <= b_buf[13];
468	                    io_in_b_14 <= b_buf[14]; io_in_b_15 <= b_buf[15];
469	                    io_in_b_16 <= b_buf[16]; io_in_b_17 <= b_buf[17];
470	                    io_in_b_18 <= b_buf[18]; io_in_b_19 <= b_buf[19];
471	                    io_in_b_20 <= b_buf[20]; io_in_b_21 <= b_buf[21];
472	                    io_in_b_22 <= b_buf[22]; io_in_b_23 <= b_buf[23];
473	                    io_in_b_24 <= b_buf[24]; io_in_b_25 <= b_buf[25];
474	                    io_in_b_26 <= b_buf[26]; io_in_b_27 <= b_buf[27];
475	                    io_in_b_28 <= b_buf[28]; io_in_b_29 <= b_buf[29];
476	                    io_in_b_30 <= b_buf[30]; io_in_b_31 <= b_buf[31];
477	
478	                    io_in_accum_0  <= acc_buf[0];  io_in_accum_1  <= acc_buf[1];
479	                    io_in_accum_2  <= acc_buf[2];  io_in_accum_3  <= acc_buf[3];
480	                    io_in_accum_4  <= acc_buf[4];  io_in_accum_5  <= acc_buf[5];
481	                    io_in_accum_6  <= acc_buf[6];  io_in_accum_7  <= acc_buf[7];
482	                    io_in_accum_8  <= acc_buf[8];  io_in_accum_9  <= acc_buf[9];
483	                    io_in_accum_10 <= acc_buf[10]; io_in_accum_11 <= acc_buf[11];
484	                    io_in_accum_12 <= acc_buf[12]; io_in_accum_13 <= acc_buf[13];
485	                    io_in_accum_14 <= acc_buf[14]; io_in_accum_15 <= acc_buf[15];
486	                    io_in_accum_16 <= acc_buf[16]; io_in_accum_17 <= acc_buf[17];
487	                    io_in_accum_18 <= acc_buf[18]; io_in_accum_19 <= acc_buf[19];
488	                    io_in_accum_20 <= acc_buf[20]; io_in_accum_21 <= acc_buf[21];
489	                    io_in_accum_22 <= acc_buf[22]; io_in_accum_23 <= acc_buf[23];
490	                    io_in_accum_24 <= acc_buf[24]; io_in_accum_25 <= acc_buf[25];
491	                    io_in_accum_26 <= acc_buf[26]; io_in_accum_27 <= acc_buf[27];
492	                    io_in_accum_28 <= acc_buf[28]; io_in_accum_29 <= acc_buf[29];
493	                    io_in_accum_30 <= acc_buf[30]; io_in_accum_31 <= acc_buf[31];
494	
495	                    io_ctrl_use_accum <= 1'b1;
496	                    io_ctrl_keep      <= 1'b0;
497	                    io_ctrl_busy      <= 1'b1;
498	                    state             <= S_WAIT_CLCT;
499	                end
500	
501	                // ----------------------------------------------------------
502	                // Wait for MMALU to finish (io_clct)
503	                // ----------------------------------------------------------
504	                S_WAIT_CLCT: begin
505	                    io_ctrl_busy <= 1'b0;
506	                    io_ctrl_keep <= 1'b1;
507	                    if (io_clct) begin
508	                        out_buf[0]  <= io_out_0;  out_buf[1]  <= io_out_1;
509	                        out_buf[2]  <= io_out_2;  out_buf[3]  <= io_out_3;
510	                        out_buf[4]  <= io_out_4;  out_buf[5]  <= io_out_5;
511	                        out_buf[6]  <= io_out_6;  out_buf[7]  <= io_out_7;
512	                        out_buf[8]  <= io_out_8;  out_buf[9]  <= io_out_9;
513	                        out_buf[10] <= io_out_10; out_buf[11] <= io_out_11;
514	                        out_buf[12] <= io_out_12; out_buf[13] <= io_out_13;
515	                        out_buf[14] <= io_out_14; out_buf[15] <= io_out_15;
516	                        out_buf[16] <= io_out_16; out_buf[17] <= io_out_17;
517	                        out_buf[18] <= io_out_18; out_buf[19] <= io_out_19;
518	                        out_buf[20] <= io_out_20; out_buf[21] <= io_out_21;
519	                        out_buf[22] <= io_out_22; out_buf[23] <= io_out_23;
520	                        out_buf[24] <= io_out_24; out_buf[25] <= io_out_25;
521	                        out_buf[26] <= io_out_26; out_buf[27] <= io_out_27;
522	                        out_buf[28] <= io_out_28; out_buf[29] <= io_out_29;
523	                        out_buf[30] <= io_out_30; out_buf[31] <= io_out_31;
524	                        io_ctrl_keep <= 1'b0;
525	                        state        <= S_WR_AW;
526	                        beat_cnt     <= 4'd0;
527	                    end
528	                end
529	
530	                // ----------------------------------------------------------
531	                // Write result to DDR (128 B, 8 beats, ARLEN=7)
532	                //
533	                // V10 BUG FIX: the original S_WR_W had an off-by-one because
534	                // `m_axi_wdata` was only updated AFTER each accepted handshake
535	                // (via NB inside the IF branch). The very first beat sent
536	                // therefore carried the stale wdata value from the previous
537	                // burst (or from reset/initial), and the body's `bc*4` index
538	                // ran from 0..6 over 7 handshakes, but the 8th handshake (with
539	                // wlast=1) advanced wdata to `bc=7*4 = out_buf[28..31]` AFTER
540	                // its own wdata had already been latched (= out_buf[24..27]).
541	                // Net effect: out_buf[28..31] was never sent to DDR3, and the
542	                // host saw an off-by-one shift in OUT.
543	                //
544	                // The fix has two parts:
545	                //   (a) Pre-load m_axi_wdata with out_buf[0..3] AT the AW
546	                //       handshake (S_WR_AW → S_WR_W transition).
547	                //   (b) In S_WR_W's IF branch, advance the NEXT wdata to
548	                //       out_buf[(beat_cnt+1)*4 + 0..3] so that beat N carries
549	                //       out_buf[N*4 + 0..3] and the final beat (bc=7, wlast=1)
550	                //       sends out_buf[28..31] correctly.
551	                // ----------------------------------------------------------
552	                S_WR_AW: begin
553	                    m_axi_awaddr  <= DEFAULT_BASE_OUT;
554	                    m_axi_awlen   <= ARLEN_FULL;
555	                    m_axi_awvalid <= 1'b1;
556	                    if (m_axi_awready && m_axi_awvalid) begin
557	                        m_axi_awvalid <= 1'b0;
558	                        m_axi_wvalid  <= 1'b1;
559	                        m_axi_wlast   <= 1'b0;
560	                        // (a) Pre-load the FIRST beat data so that handshake 0
561	                        // in S_WR_W carries out_buf[0..3] (not stale data).
562	                        m_axi_wdata   <= {
563	                            out_buf[3], out_buf[2], out_buf[1], out_buf[0]
564	                        };
565	                        state         <= S_WR_W;
566	                    end
567	                end
568	
569	                S_WR_W: begin
570	                    if (m_axi_wready && m_axi_wvalid) begin
571	                        // (b) Advance to NEXT beat's data for the upcoming
572	                        // handshake. Indexing (beat_cnt+1)*4 means after
573	                        // handshake N (bc=N), wdata is set up for beat N+1.
574	                        m_axi_wdata <= {
575	                            out_buf[(beat_cnt + 1)*4 + 3],
576	                            out_buf[(beat_cnt + 1)*4 + 2],
577	                            out_buf[(beat_cnt + 1)*4 + 1],
578	                            out_buf[(beat_cnt + 1)*4 + 0]
579	                        };
580	                        beat_cnt <= beat_cnt + 1;
581	                        if (beat_cnt == 4'd6)
582	                            m_axi_wlast <= 1'b1;
583	                        if (m_axi_wlast) begin
584	                            m_axi_wvalid <= 1'b0;
585	                            m_axi_bready <= 1'b1;
586	                            state        <= S_WR_B;
587	                        end
588	                    end
589	                    // No need for an else branch any more — wdata is
590	                    // pre-loaded in S_WR_AW and advanced lock-step with
591	                    // beat_cnt, so it stays at the correct beat value across
592	                    // any back-pressure cycle (wready=0).
593	                end
594	
595	                S_WR_B: begin
596	                    if (m_axi_bvalid && m_axi_bready) begin
597	                        m_axi_bready <= 1'b0;
598	                        state        <= S_DONE;
599	                    end
600	                end
601	
602	                S_DONE: begin
603	                    done  <= 1'b1;
604	                    busy  <= 1'b0;
605	                    state <= S_IDLE;
606	                end
607	
608	                default: state <= S_IDLE;
609	            endcase
610	        end
611	    end
612	
613	endmodule
